882 :          * x and look up the exp function of it.
883 :          * fracPartA will have the upper 22 bits, fracPartB the lower 52 bits.
884 :          */
885 :         final int intFrac = (int) ((x - intVal) * 1024.0);
886 :         final double fracPartA = ExpFracTable.EXP_FRAC_TABLE_A[intFrac];
887 :         final double fracPartB = ExpFracTable.EXP_FRAC_TABLE_B[intFrac];
888 : 
889 :         /* epsilon is the difference in x from the nearest multiple of 2^-10.  It
890 :          * has a value in the range 0 <= epsilon < 2^-10.
891 :          * Do the subtraction from x as the last step to avoid possible loss of percison.
892 :          */
893 :         final double epsilon = x - (intVal + intFrac / 1024.0);
894 : 
895 :         /* Compute z = exp(epsilon) - 1.0 via a minimax polynomial.  z has
896 :        full double precision (52 bits).  Since z < 2^-10, we will have
897 :        62 bits of precision when combined with the contant 1.  This will be
898 :        used in the last addition below to get proper rounding. */
899 : 
900 :         /* Remez generated polynomial.  Converges on the interval [0, 2^-10], error
901 :        is less than 0.5 ULP */
902 :         double z = 0.04168701738764507;
903 :         z = z * epsilon + 0.1666666505023083;
904 :         z = z * epsilon + 0.5000000000042687;
905 :         z = z * epsilon + 1.0;
906 :         z = z * epsilon + -3.940510424527919E-20;
907 : 
908 :         /* Compute (intPartA+intPartB) * (fracPartA+fracPartB) by binomial
909 :        expansion.
910 :        tempA is exact since intPartA and intPartB only have 22 bits each.
911 :        tempB will have 52 bits of precision.
912 :          */
913 :         double tempA = intPartA * fracPartA;
914 :         double tempB = intPartA * fracPartB + intPartB * fracPartA + intPartB * fracPartB;
915 : 
916 :         /* Compute the result.  (1+z)(tempA+tempB).  Order of operations is
917 :        important.  For accuracy add by increasing size.  tempA is exact and
918 :        much larger than the others.  If there are extra bits specified from the
919 :        pow() function, use them. */
920 :         final double tempC = tempB + tempA;
921 :         final double result;
922 :         if (extra != 0.0) {
923 :             result = tempC*extra*z + tempC*extra + tempC*z + tempB + tempA;
924 :         } else {
925 :             result = tempC*z + tempB + tempA;
926 :         }
927 : 
928 :         if (hiPrec != null) {
929 :             // If requesting high precision
930 :             hiPrec[0] = tempA;
931 :             hiPrec[1] = tempC*extra*z + tempC*extra + tempC*z + tempB;
932 :         }
933 : 
934 :         return result;
